mapper.select:
SELECT t.id, t.sku_id, t.sku_code, t.sku_name, t.spec_text, t.order_item_id, t.stock_order_id,
       t.type, t.reason, t.qty, t.balance_after, t.operator_id, t.operator_name, t.remark, t.create_time,
       o.order_no AS orderNo
FROM stock_transaction t
LEFT JOIN stock_order o ON o.id = t.stock_order_id

    AND t.sku_id = #{skuId}

        AND (t.sku_code LIKE CONCAT('%', #{search}, '%') OR t.sku_name LIKE CONCAT('%', #{search}, '%'))

    AND t.type = #{type}
    AND t.reason = #{reason}
    AND t.order_item_id = #{orderItemId}
    AND t.create_time >= #{startTime}
    AND t.create_time < DATE_ADD(#{endTime}, INTERVAL 1 DAY)

ORDER BY t.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1) FROM stock_transaction t

    AND t.sku_id = #{skuId}

        AND (t.sku_code LIKE CONCAT('%', #{search}, '%') OR t.sku_name LIKE CONCAT('%', #{search}, '%'))

    AND t.type = #{type}
    AND t.reason = #{reason}
    AND t.order_item_id = #{orderItemId}
    AND t.create_time >= #{startTime}
    AND t.create_time < DATE_ADD(#{endTime}, INTERVAL 1 DAY)
